-- Q3540: System Availability and Change Management [easy/L1]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["Automatic failover to surviving nodes, minimizing service downtime","Faster internet connectivity for all end users","Improved physical security of the data center facility","Encryption of data stored on disk at rest"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (A): Per NIST SP 800-34 Rev. 1 Section 5.1.1, server clustering groups multiple servers to function as a single system, providing automatic failover when one node fails. The surviving nodes absorb the failed node''s workload, minimizing or eliminating downtime.
Wrong (B): Clustering addresses server-level redundancy, not network bandwidth or internet speed for end users.
Wrong (C): Physical security involves facility access controls and surveillance, which are unrelated to server clustering.
Wrong (D): Disk encryption protects data confidentiality but does not provide the availability benefit that clustering delivers through redundancy.$EXPL$
WHERE id = 3540;

-- Q3541: System Availability and Change Management [easy/L1]
-- Issues: #1, #3
